(() => {
  'use strict';
  window.FieldManager={create(adapter){
    const $=id=>document.getElementById(id),F=window.FieldFormats;
    let recordId=null,exportIds=[],prepared=null,returnRecordId=null;
    const dialogs=['filesDialog','recordDialog','exportDialog'].map($);
    function closeAll(){dialogs.forEach(d=>{if(d.open)d.close()})}
    function show(id){closeAll();$(id).showModal()}
    function selected(){return adapter.getFeatures().filter(f=>exportIds.includes(String(f.id)))}
    function displayDate(f){const p=f.properties;const d=new Date(p.captured_at||p.ended_at||p.created_at||p.saved_at);return Number.isNaN(d.getTime())?'':d.toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'})}
    const number=(n,d=2)=>n.toLocaleString('pt-BR',{minimumFractionDigits:d,maximumFractionDigits:d});
    function description(f){const m=F.stats(f);return m.type+(m.polygon?' · '+number(m.area/10000,4)+' ha · '+number(m.length)+' m':f.geometry.type.includes('Line')?' · '+number(m.length)+' m':'')}
    function button(label,action,kind='secondary-btn'){const b=document.createElement('button');b.type='button';b.className=kind;b.textContent=label;b.addEventListener('click',action);return b}
    function preview(f){const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox','0 0 96 72');svg.setAttribute('aria-hidden','true');svg.classList.add('file-thumb');const all=F.parts(f.geometry).flatMap(p=>p.points),origin=all[0],cos=Math.cos(origin[1]*Math.PI/180),project=c=>[(c[0]-origin[0])*cos,c[1]-origin[1]],bounds=[Infinity,Infinity,-Infinity,-Infinity];all.forEach(c=>{const[x,y]=project(c);bounds[0]=Math.min(bounds[0],x);bounds[1]=Math.min(bounds[1],y);bounds[2]=Math.max(bounds[2],x);bounds[3]=Math.max(bounds[3],y)});const scale=Math.min(70/Math.max(bounds[2]-bounds[0],.00001),48/Math.max(bounds[3]-bounds[1],.00001)),transform=c=>{const[x,y]=project(c);return[48+(x-(bounds[0]+bounds[2])/2)*scale,36-(y-(bounds[1]+bounds[3])/2)*scale]};for(const p of F.parts(f.geometry)){if(p.points.length===1){const[x,y]=transform(p.points[0]),dot=document.createElementNS(ns,'circle');dot.setAttribute('cx',x);dot.setAttribute('cy',y);dot.setAttribute('r',4);svg.appendChild(dot)}else{const path=document.createElementNS(ns,'path'),step=Math.max(1,Math.ceil(p.points.length/500));let pts=p.points.filter((_,i)=>i%step===0);if(pts.at(-1)!==p.points.at(-1))pts.push(p.points.at(-1));path.setAttribute('d',pts.map((c,i)=>(i?'L':'M')+transform(c).join(',')).join(' ')+(p.closed?'Z':''));path.setAttribute('fill',p.closed?'rgba(88,223,145,.18)':'none');svg.appendChild(path)}}return svg}
    function renderFiles(){renderDocuments();$('filesUndo').hidden=!adapter.canUndo?.();const features=adapter.getFeatures(),query=$('filesSearch').value.trim().toLocaleLowerCase('pt-BR'),filter=$('filesType').value,list=$('filesList');list.replaceChildren();const shown=features.filter(f=>{const type=f.geometry.type;return(!query||String(f.properties.name).toLocaleLowerCase('pt-BR').includes(query))&&(!filter||(filter==='area'?type.includes('Polygon'):filter==='point'?type.includes('Point'):type.includes('Line')))}).slice().reverse();$('filesCount').textContent=(adapter.getDocuments?.().length||1)+' arquivo(s) · '+features.length+' elemento(s) no arquivo atual';$('exportAllFiles').disabled=features.length===0;if(!shown.length){const p=document.createElement('p');p.className='files-empty';p.textContent=features.length?'Nenhum arquivo encontrado.':'Seus pontos, linhas e áreas salvos aparecerão aqui.';list.appendChild(p);return}for(const f of shown){const card=document.createElement('article');card.className='saved-file';const head=document.createElement('div');head.className='file-heading';head.appendChild(preview(f));const info=document.createElement('div'),title=document.createElement('strong'),sub=document.createElement('small'),date=document.createElement('small');title.textContent=f.properties.name;sub.textContent=description(f);date.textContent=displayDate(f);info.append(title,sub,date);head.appendChild(info);card.appendChild(head);const actions=document.createElement('div');actions.className='file-actions';actions.append(button('Abrir no mapa',()=>{closeAll();adapter.openMap(f)}),button('Detalhes',()=>openRecord(f.id)),button('Exportar',()=>openExport([f.id])),button('Excluir',()=>{if(adapter.deleteFeature(f.id))renderFiles()},'secondary-btn danger-btn'));actions.classList.add('with-delete');card.appendChild(actions);list.appendChild(card)}}
    function renderDocuments(){
      const list=$('documentsList');if(!list||!adapter.getDocuments)return;list.replaceChildren();
      for(const doc of adapter.getDocuments()){
        const card=document.createElement('article');card.className='document-card';if(doc.id===adapter.getActiveDocumentId())card.classList.add('current');const name=document.createElement('strong');name.textContent=doc.name;const count=document.createElement('small'),items=adapter.getDocumentFeatures(doc.id);count.textContent=items.length+' elemento(s)'+(doc.id===adapter.getActiveDocumentId()?' · Aberto agora':'');card.append(name,count);
        const actions=document.createElement('div');actions.className='file-actions';actions.append(button('Abrir',()=>{if(adapter.activateDocument(doc.id))closeAll()}),button('Renomear',()=>{closeAll();adapter.editDocument(doc.id)}));const exportButton=button('Exportar',()=>{if(adapter.activateDocument(doc.id))openExport()});exportButton.disabled=!items.length;actions.appendChild(exportButton);actions.appendChild(button('Excluir arquivo',()=>{if(adapter.deleteDocument(doc.id))renderFiles()},'secondary-btn danger-btn'));actions.classList.add('with-delete');card.appendChild(actions);list.appendChild(card);
      }
    }
    function openFiles(){renderFiles();show('filesDialog')}
    function openRecord(id){const f=adapter.getFeatures().find(f=>String(f.id)===String(id));if(!f)return;recordId=String(f.id);$('recordName').value=f.properties.name;$('recordNotes').value=f.properties.notes||'';$('recordMetrics').textContent=description(f)+(F.stats(f).polygon?' · '+number(F.stats(f).area)+' m²':'');$('recordDate').textContent=displayDate(f);$('recordPreview').replaceChildren(preview(f));$('recordStatus').textContent='Salvo em '+(adapter.getDocumentName?.()||'Meus arquivos')+' neste aparelho';show('recordDialog')}
    function saveEdits(){const f=adapter.getFeatures().find(f=>String(f.id)===recordId);if(!f)return null;const name=$('recordName').value.trim();if(!name){$('recordStatus').textContent='Informe um nome para o arquivo.';$('recordName').focus();return null}const result=adapter.updateFeature(recordId,{name:name.slice(0,100),notes:$('recordNotes').value.trim().slice(0,2000)});if(!result){$('recordStatus').textContent='Não foi possível salvar. Exporte uma cópia e tente novamente.';return null}$('recordStatus').textContent='Alterações salvas em Meus arquivos';return result}
    function prepare(){prepared=null;$('downloadFile').disabled=true;$('shareFile').disabled=true;try{const packet=F.build($('exportFormat').value,selected()),name=$('exportName').value.trim();if(!name)throw Error('Informe um nome para o arquivo.');const ext=F.formats.find(f=>f.id===$('exportFormat').value).ext;packet.name=F.slug(name.replace(/\.(pdf|kml|kmz|geojson|json|zip|dxf|csv|gpx)$/i,''))+'.'+ext;prepared={packet,file:new File([packet.bytes],packet.name,{type:packet.mime})};$('exportInfo').textContent=packet.name+' · '+number(packet.bytes.length/1024,1)+' KB';$('exportStatus').textContent='Arquivo pronto. Escolha baixar ou compartilhar.';$('downloadFile').disabled=false;$('shareFile').disabled=false}catch(e){$('exportStatus').textContent=e.message||'Não foi possível preparar o arquivo.';$('exportInfo').textContent=''}}
    function openExport(ids,fromRecord=null){exportIds=(ids||adapter.getFeatures().map(f=>f.id)).map(String);returnRecordId=fromRecord;if(!selected().length){adapter.notify('Salve um mapeamento antes de exportar.');return}$('exportScope').textContent=!ids?(adapter.getDocumentName?.()||'Meu mapa')+' · '+selected().length+' elemento(s)':selected().length===1?selected()[0].properties.name:selected().length+' elementos selecionados';$('exportName').value=!ids?(adapter.getDocumentName?.()||'Meu mapa'):selected().length===1?selected()[0].properties.name:'Meu mapa';show('exportDialog');prepare()}
    function download(){if(!prepared)return;const blob=new Blob([prepared.packet.bytes],{type:prepared.packet.mime}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=prepared.packet.name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);$('exportStatus').textContent='Arquivo gerado. No iPhone, use Salvar em Arquivos se o navegador abrir uma prévia.'}
    async function share(){if(!prepared)return;const file=prepared.file;if(!navigator.share||!navigator.canShare||!navigator.canShare({files:[file]})){$('exportStatus').textContent='Este navegador não compartilha este tipo de arquivo. Use Baixar e anexe como documento no WhatsApp, ou escolha PDF.';return}try{await navigator.share({files:[file]});$('exportStatus').textContent='Arquivo entregue ao compartilhamento do aparelho.'}catch(e){if(e.name!=='AbortError')$('exportStatus').textContent='Não foi possível compartilhar. Use Baixar e envie o arquivo como documento.'}}
    $('closeFiles').addEventListener('click',()=>closeAll());$('closeRecord').addEventListener('click',()=>closeAll());$('closeExport').addEventListener('click',()=>{closeAll();if(returnRecordId)openRecord(returnRecordId)});
    $('filesUndoButton').addEventListener('click',()=>{if(adapter.undoDelete())renderFiles()});
    $('filesSearch').addEventListener('input',renderFiles);$('filesType').addEventListener('change',renderFiles);$('exportAllFiles').addEventListener('click',()=>openExport());
    $('recordForm').addEventListener('submit',e=>{e.preventDefault();if(saveEdits()){closeAll();adapter.notify('Arquivo salvo em Meus arquivos.')}});
    $('recordOpenMap').addEventListener('click',()=>{const f=saveEdits();if(f){closeAll();adapter.openMap(f)}});$('recordExport').addEventListener('click',()=>{const f=saveEdits();if(f)openExport([f.id],String(f.id))});
    for(const fmt of F.formats){const option=document.createElement('option');option.value=fmt.id;option.textContent=fmt.label+' — '+fmt.description;$('exportFormat').appendChild(option)}
    $('exportName').addEventListener('input',prepare);$('exportFormat').addEventListener('change',prepare);$('downloadFile').addEventListener('click',download);$('shareFile').addEventListener('click',share);
    return{openFiles,openRecord,openExport};
  }};
})();
